int t040() {
  std::cout << "T-040 analogue pickup RLC and load model vs oracle (1e-12)\n";
  const Json j = a03::oracle();
  int n = 0;
  for (const auto& e : j["load"].arr) {
    check(a03::relEq(egb::phys::loadResistanceOhm(e.numAt("pot_kohm"), e.numAt("amp_mohm")), e.numAt("rload"), 1e-12), "load resistance");
    ++n;
  }
  check(a03::relEq(egb::phys::loadResistanceOhm(250, 1.0), 111111.11111111111, 1e-12), "250 kOhm pots + 1 MOhm = 111.1 kOhm (C-012)");
  for (const auto& e : j["rlc"].arr) {
    auto a = egb::phys::rlcAnalog((int)e.numAt("type"), e.numAt("pot_kohm"), e.numAt("cable_pf"), e.numAt("amp_mohm"));
    const bool ok = a03::relEq(a.a2, e.numAt("a2"), 1e-12) && a03::relEq(a.a1, e.numAt("a1"), 1e-12) &&
                    a03::relEq(a.a0, e.numAt("a0"), 1e-12) && a03::relEq(a.fresHz, e.numAt("fres"), 1e-12) &&
                    a03::relEq(a.q, e.numAt("q"), 1e-12) && a03::relEq(a.rloadOhm, e.numAt("rload"), 1e-12) &&
                    a03::relEq(a.ctotalF, e.numAt("ctotal"), 1e-12);
    if (!ok) { check(false, "rlc entry " + std::to_string(n)); break; }
    ++n;
  }
  for (int t = 0; t < 3; ++t) {
    auto c = egb::phys::coilParams(t);
    check(std::isfinite(c.inductanceH) && c.inductanceH > 1.0 && c.inductanceH < 10.0, "coil inductance within 1-10 H (C-011)");
  }
  std::cout << "  checked " << n << " entries\n";
  return failures ? 1 : 0;
}

int t041() {
  std::cout << "T-041 prewarped digital RLC biquad vs oracle (1e-10) at four rates\n";
  const Json j = a03::oracle();
  for (const auto& e : j["digital"].arr) {
    const double fs = e.numAt("fs");
    auto a = egb::phys::rlcAnalog((int)e.numAt("type"), 250.0, 600.0, 1.0);
    auto b = egb::phys::rlcDigital(a, fs);
    const auto& c = e["coeffs"].arr;
    const bool ok = c.size() == 5 && a03::relEq(b.b0, c[0].num, 1e-10) && a03::relEq(b.b1, c[1].num, 1e-10) &&
                    a03::relEq(b.b2, c[2].num, 1e-10) && a03::relEq(b.a1, c[3].num, 1e-10) && a03::relEq(b.a2, c[4].num, 1e-10);
    check(ok, "biquad coefficients type " + std::to_string((int)e.numAt("type")) + " fs " + std::to_string((int)fs));
    // stability: poles inside the unit circle (|a2| < 1 and |a1| < 1 + a2)
    check(std::abs(b.a2) < 1.0 && std::abs(b.a1) < 1.0 + b.a2, "biquad stable");
  }
  return failures ? 1 : 0;
}

int t042() {
  std::cout << "T-042 spatial sampling: position, aperture and humbucker two-pole comb vs oracle (1e-12)\n";
  const Json j = a03::oracle();
  size_t n = 0;
  for (const auto& e : j["spatial"].arr) {
    const double s = egb::phys::pickupSpatial((int)e.numAt("m"), e.numAt("xp"), e.numAt("Ls"), (int)e.numAt("type"));
    if (!a03::relEq(s, e.numAt("s"), 1e-12)) { check(false, "spatial entry " + std::to_string(n)); break; }
    ++n;
  }
  check(n == j["spatial"].arr.size(), "all spatial entries match");
  check(egb::phys::kHumbuckerPoleSpacingM == 0.0185 && egb::phys::kHumbuckerSecondCoilDb == -2.5, "humbucker constants (C-019)");
  // single coil: point response equals sin(k x) * aperture; at a node the weight is zero
  const double Ls = 0.6477, xp = Ls / 4.0;
  check(std::abs(egb::phys::pickupSpatial(4, xp, Ls, 0)) < 1e-12, "single coil at L/4 nulls mode 4");
  for (int m = 1; m <= 80; ++m) {
    const double h = egb::phys::horizontalCoupling(m * 110.0, 0);
    if (!(h > 0.0 && h <= 1.0)) { check(false, "horizontal coupling in (0,1]"); break; }
  }
  return failures ? 1 : 0;
}

